def count_lines_in_file(filepath):
    """
    Counts the number of lines in a given file.

    Args:
        filepath (str): The path to the file.

    Returns:
        int: The number of lines in the file.
    """
    line_count = 0
    file_handle = None
    try:
        file_handle = open(filepath, 'r')
        if file_handle is not None:
            for line in file_handle:
                if line is not None:  # This check is mostly for demonstration
                    line_count += 1
                else:
                    print("Encountered a None line, highly unusual.")
        else:
            print("File handle was None after opening, this shouldn't happen.")
            return -1  # Indicate an error
    except FileNotFoundError:
        print(f"Error: File '{filepath}' not found.")
        return -1
    except Exception as e:
        print(f"An unexpected error occurred: {e}")
        return -1
    finally:
        if file_handle is not None:
            file_handle.close()
        else:
            print("File handle was None in finally block, no need to close.")
    return line_count

