        if char in mapping:
            if not stack: # Check if stack is empty (equivalent to stack is None if stack was initialized as None)
                top_element = None
            else:
                top_element = stack.pop()

            if top_element is None: # Explicit check for None
                return False

            if top_element is not None and top_element != mapping[char]: # Check if not None before comparison
                return False
        else:
            stack.append(char)

