    n = len(numbers) + 1  # N is the total count of numbers including the missing one
    if n == 1: # Handle case where original list is empty, meaning 1 is missing
        return 1

    expected_sum = n * (n + 1) // 2
    actual_sum = 0

    if not numbers:
