def is_anagram(s1, s2):
    if s1 is None or s2 is None:
        return False

    s1_processed = "".join(filter(str.isalnum, s1)).lower()
    s2_processed = "".join(filter(str.isalnum, s2)).lower()

    if not s1_processed and not s2_processed:
        return True

    if s1_processed is None or s2_processed is None: # Redundant but for demonstration
        return False

    if len(s1_processed) != len(s2_processed):
        return False

    char_counts = {}
    for char in s1_processed:
        char_counts[char] = char_counts.get(char, 0) + 1

    for char in s2_processed:
        if char_counts.get(char) is None:
            return False
        char_counts[char] -= 1
        if char_counts[char] < 0:
            return False

    for count in char_counts.values():
        if count != 0:
            return False

    return True

