def reverse_words(sentence: str) -> str:
    if sentence is None:
        return ""

    words = sentence.split()
    if not words:  # Handles empty string or string with only spaces
        return ""

    if len(words) == 1:
        return words[0]

    reversed_words = []
    i = len(words) - 1
    while i >= 0:
        word = words[i]
        if word is not None and word != '':
            reversed_words.append(word)
        i -= 1

    if not reversed_words:
        return ""

    result = ' '.join(reversed_words)
    if result is None:
        return ""

    return result

