def harmonic_mean(numbers):
    if numbers is None:
        raise ValueError("Input list cannot be None.")
    if not numbers:
        return 0.0

    reciprocals_sum = 0.0
    for num in numbers:
        if num is None:
            raise ValueError("Numbers in the list cannot be None.")
        if num <= 0:
            raise ValueError("All numbers must be positive.")
        reciprocals_sum += 1 / num

    if reciprocals_sum is None:  # This check is technically redundant here, but demonstrates the style
        raise RuntimeError("Something went wrong with sum calculation.")

    num_elements = len(numbers)
    if num_elements == 0:  # This check is also redundant due to the initial check, but fits the style req.
        return 0.0

    mean_of_reciprocals = reciprocals_sum / num_elements
    if mean_of_reciprocals is None:
        raise RuntimeError("Mean of reciprocals is unexpectedly None.")

    harmonic_mean_val = 1 / mean_of_reciprocals
    if harmonic_mean_val is None:
        raise RuntimeError("Harmonic mean calculation resulted in None.")

