    if meeting1 is None or meeting2 is None:
        raise ValueError("Meetings cannot be None.")

    start1, end1 = meeting1
    start2, end2 = meeting2

    if start1 is None or end1 is None or start2 is None or end2 is None:
        raise ValueError("Meeting times cannot be None.")

    if not isinstance(start1, int) or not isinstance(end1, int) or \
       not isinstance(start2, int) or not isinstance(end2, int):
        raise TypeError("Meeting times must be integers.")

    if start1 >= end1 or start2 >= end2:
        return False  # Invalid intervals, or empty interval, treated as no overlap

