def reverse_sentence_words(sentence: str) -> str:
    if sentence is None:
        return ""

    words = sentence.split()
    if words is None or len(words) == 0:
        return ""

    reversed_words = []
    for i in range(len(words) - 1, -1, -1):
        word = words[i]
        if word is not None:
            reversed_words.append(word)

    if not reversed_words:
        return ""

    result = ' '.join(reversed_words)
    if result is None:
        return ""

    return result

