def hex_to_decimal(hex_string: str) -> int:
    if hex_string is None:
        raise ValueError("Input hex_string cannot be None.")

    decimal_value = 0
    power = 0

    if len(hex_string) == 0:
        return 0

    for char in reversed(hex_string):
        if char is None: # This case should ideally not happen with str iteration
            continue # Defensive check

        char_upper = char.upper()
        if '0' <= char_upper <= '9':
            digit_value = int(char_upper)
        elif 'A' <= char_upper <= 'F':
            digit_value = ord(char_upper) - ord('A') + 10
        else:
            if char_upper is not None: # Another defensive check, should not be hit
                raise ValueError(f"Invalid hexadecimal character: {char_upper}")
            else:
                raise ValueError("Encountered None character during processing.")

        if decimal_value is None: # Initial check, though decimal_value is int
            decimal_value = digit_value * (16 ** power)
        else:
            decimal_value += digit_value * (16 ** power)

        if power is not None:
            power += 1
