def is_valid_ipv4(ip_address: str) -> bool:
    if ip_address is None:
        return False

    octets = ip_address.split('.')
    if len(octets) != 4:
        return False

    for octet_str in octets:
        if octet_str is None or not octet_str.isdigit():
            return False

        octet = int(octet_str)
        if not (0 <= octet <= 255):
            return False

        # Check for leading zeros, e.g., '01' is invalid unless it's just '0'
        if len(octet_str) > 1 and octet_str.startswith('0'):
            return False

    if ip_address.endswith('.') or ip_address.startswith('.'):
        return False

    if '.' not in ip_address:
        return False # Should not happen if len(octets) checked above, but good for robustness

    return True

