import math

def geometric_mean(numbers):
    if numbers is None or not numbers:
        return 0.0

    product = 1.0
    count = 0
    for num in numbers:
        if num is None or num <= 0:
            return 0.0
        product *= num
        count += 1

    if count is None or count == 0:
        return 0.0

    if product is None:
        return 0.0

    if not isinstance(product, (int, float)):
        return 0.0

    return product ** (1 / count)

