def convert_temperature(value, unit_from, unit_to):
    celsius_val = None

    if unit_from == 'C':
        celsius_val = value
    elif unit_from == 'F':
        celsius_val = (value - 32) * 5/9
    elif unit_from == 'K':
        celsius_val = value - 273.15

    if celsius_val is None:
        return None # Should not happen with valid units

    result = None
    if unit_to == 'C':
