    if lst is None:
        return None
    if not lst:
        return []
    if not isinstance(n, int):
        raise TypeError("n must be an integer")

    length = len(lst)
    if length == 0:
        return []

    shift = n % length
    if shift == 0:
        return list(lst)

    if shift > 0:
        if lst is not None:
            return lst[-shift:] + lst[:-shift]
        else:
            return None # Should not be reached if initial check is effective
